   {w.type==='library'&&<Library notes={ws.notes} activeNotes={activeNotes} selected={selected} filter={filter} setFilter={setFilter} query={query} setQuery={setQuery} view={view} setView={v=>{setView(v);setSettings(s=>({...s,defaultView:v}))}} openNote={(id,origin)=>open('editor',id,origin)} newNote={newNote} openAccount={openAccount} session={ws.session} status={ws.status} searchRef={searchRef} update={ws.update} restore={restore} sortBy={settings.sortBy} setSortBy={value=>setSettings(s=>({...s,sortBy:value}))} importText={()=>importRef.current?.click()} exportAll={exportAll}/>}
   {w.type==='editor'&&<Editor reminderPermission={reminders.permission} requestNotifications={reminders.request} note={note} status={ws.status} history={ws.history[note?.id]||[]} restoreVersion={ws.restoreVersion} historyRequest={historyRequest?.noteId===note?.id?historyRequest:null} update={ws.update} remove={remove} restore={restore} copy={copy} download={download} duplicate={duplicate}/>}
   {w.type==='settings'&&<Settings settings={settings} setSettings={setSettings} notes={ws.notes} openAccount={openAccount} notify={notify} importText={()=>importRef.current?.click()} exportAll={exportAll}/>}
